<script setup lang="ts">
import PufferMark from './PufferMark.vue';
import QR from 'qrcode/lib/core/qrcode';
import {ref,onMounted,watch} from 'vue';import {memberApi,getServiceBase} from '@/services/api';
const props=defineProps<{demo?:boolean;accountOnly?:boolean}>();const profile=ref<any>(null),plans=ref<any[]>([]),orders=ref<any[]>([]),username=ref(''),password=ref(''),password2=ref(''),register=ref(false),busy=ref(false),message=ref(''),mode=ref('account'),config=ref<any>({}),payUrl=ref(''),pending=ref<any>(null),payMethod=ref('alipay'),qrRows=ref<boolean[][]>([]),amount=ref(10),period=ref('month');
const emit=defineEmits<{profile:[value:any];account:[]}>();watch(profile,v=>emit('profile',v),{deep:true});
let platform='web';
// #ifdef APP-PLUS
platform=uni.getSystemInfoSync().platform==='ios'?'ios':'android';
// #endif
async function run(action:()=>Promise<void>){busy.value=true;message.value='';try{await action();}catch(e){message.value=(e as Error).message;}finally{busy.value=false;}}
async function refresh(){await run(async()=>{config.value=await memberApi.config();if(uni.getStorageSync('hetun-member-token'))profile.value=(await memberApi.profile()).profile;if(config.value.configured&&!props.accountOnly){const result=await memberApi.plans();plans.value=result.groups||[];}});}
async function login(){await run(async()=>{profile.value=(await memberApi.login(username.value,password.value,register.value,password2.value)).profile;password.value='';password2.value='';if(!props.accountOnly)plans.value=(await memberApi.plans()).groups||[];message.value='已登录苹果 CMS 账号。';});}
async function logout(){await run(async()=>{await memberApi.logout();profile.value=null;orders.value=[];pending.value=null;payUrl.value='';qrRows.value=[];});}
async function showOrders(){mode.value='orders';await run(async()=>{orders.value=(await memberApi.orders()).orders;});}
async function purchase(id:number,points=false){await run(async()=>{if(platform==='ios'&&!points)throw new Error('iOS 内购尚未配置，当前无法在 App 内购买会员。');const result=points?await memberApi.upgrade(id,period.value):await memberApi.purchase(id,period.value,platform);pending.value=points?null:result.order;payUrl.value='';qrRows.value=[];message.value=points?'升级结果已由 CMS 确认。':'订单已由 CMS 创建，支付结果需要点击订单查询确认。';profile.value=(await memberApi.profile()).profile;});}
async function recharge(){await run(async()=>{if(platform==='ios')throw new Error('iOS 内购尚未配置。');const v=await memberApi.recharge(Number(amount.value),platform);pending.value=v.order;payUrl.value='';qrRows.value=[];message.value='充值订单已创建，支付完成后请查询订单状态。';});}
async function check(code:string){await run(async()=>{const result=await memberApi.order(code);message.value=Number(result.order.order_status)===1?'CMS 已确认支付成功。':'CMS 尚未确认支付。';orders.value=(await memberApi.orders()).orders;profile.value=(await memberApi.profile()).profile;});}
async function checkout(order=pending.value){await run(async()=>{if(platform==='ios')throw new Error('iOS 内购尚未配置。');pending.value=order;payUrl.value='';qrRows.value=[];const v=await memberApi.checkout(Number(order.order_id),order.order_code,payMethod.value,platform);if(v.kind==='qrcode'){const m=QR.create(v.code,{errorCorrectionLevel:'M'}).modules;qrRows.value=Array.from({length:m.size},(_,r)=>Array.from({length:m.size},(_,c)=>!!m.get(r,c)));message.value='请使用相应支付 App 扫描二维码，完成后查询 CMS 订单状态。';}else {payUrl.value=v.checkoutPath?getServiceBase()+v.checkoutPath:v.url;message.value='收银台已准备，请点击前往付款。';}});}
function payment(){if(!payUrl.value)return;
// #ifdef H5
window.open(payUrl.value,'_blank','noopener,noreferrer');
// #endif
// #ifdef APP-PLUS
plus.runtime.openURL(payUrl.value);
// #endif
}
onMounted(refresh);
</script>
<template><view class="member-panel" :class="{'account-only':accountOnly}"><view v-if="!accountOnly" class="member-channel-tabs"><text :class="{active:mode==='account'}" @click="mode='account'">精选</text><text @click="profile?mode='account':emit('account')">会员套餐</text><text :class="{active:mode==='orders'}" @click="profile?showOrders():emit('account')">我的订单</text><text :class="{active:mode==='recharge'}" @click="profile?mode='recharge':emit('account')">积分充值</text></view><view class="member-head" :class="{'account-head':accountOnly}"><text v-if="!accountOnly" class="vip-crest">V</text><view class="member-person" @click="!profile&&emit('account')"><view class="member-avatar"><text v-if="profile">{{profile.user_name.slice(0,1)}}</text><PufferMark v-else :size="29" color="#27c9e3"/></view><view><text class="member-title">{{profile?.user_name||(accountOnly?'账号登录':'登录 / 注册')}}</text><text class="member-caption">{{accountOnly?'管理你的苹果 CMS 账号':profile?.member_name||'会员专属权益'}}</text></view></view><template v-if="!accountOnly"><view class="renewal-line"><text>{{profile?.member_name||'VIP 会员'}}<text class="renewal-subtitle"> {{profile?.expire_date?'到期 '+profile.expire_date:'选择适合你的会员套餐'}}</text></text></view><button class="renewal-button" @click="profile?mode='account':emit('account')">{{profile?'立即续费':'登录后开通会员'}}</button></template><text v-else-if="profile">积分 {{profile.user_points}} · 用户组 {{profile.group_id}}</text></view><view v-if="!accountOnly" class="membership-facts"><text class="facts-title">我的专享权益</text><view class="facts-grid"><view><text>会员身份</text><text>{{profile?.member_name||'登录后查看'}}</text></view><view><text>会员有效期</text><text>{{profile?.expire_date||'以 CMS 账户为准'}}</text></view><view><text>账户积分</text><text>{{profile?.user_points??'登录后查看'}}</text></view></view></view><view class="message" v-if="message">{{message}}</view><view v-if="!config.configured" class="message">尚未连接苹果 CMS。连接后可使用原账号登录和会员套餐。</view><view v-if="!profile&&accountOnly" class="login"><input v-model="username" name="cms-account" autocomplete="off" placeholder="苹果 CMS 账号"/><input v-model="password" name="cms-password" autocomplete="new-password" password placeholder="密码"/><input v-if="register" v-model="password2" password placeholder="再次输入密码"/><button :disabled="busy||!config.configured" @click="login">{{register?'注册并登录':'登录'}}</button><text @click="register=!register">{{register?'已有账号，去登录':'注册新账号'}}</text></view><view v-else-if="accountOnly" class="account-controls"><text>已登录 {{profile.user_name}}</text><button :disabled="busy" @click="logout">退出登录</button></view><template v-else-if="profile"><view class="member-tabs"><text @click="mode='account'">会员套餐</text><text @click="showOrders">我的订单</text><text @click="mode='recharge'">积分充值</text><text @click="logout">退出</text></view><template v-if="mode==='account'"><view class="periods"><text v-for="p in [{id:'day',name:'天'},{id:'week',name:'周'},{id:'month',name:'月'},{id:'year',name:'年'}]" :key="p.id" :class="{chosen:period===p.id}" @click="period=p.id">{{p.name}}套餐</text></view><view v-if="!plans.length" class="message">CMS 未返回可购买套餐，请检查站点的会员组及升级设置。</view><view v-for="g in plans" :key="g.group_id" class="plan"><text>{{g.group_name}}</text><text>现金 ¥{{g['price_'+period]??'未配置'}} / 积分 {{g['group_points_'+period]??'未配置'}}</text><button :disabled="busy||platform==='ios'||!Number(g['price_'+period])" @click="purchase(Number(g.group_id))">购买 / 续费</button><button :disabled="busy||!Number(g['group_points_'+period])" @click="purchase(Number(g.group_id),true)">CMS 积分升级</button></view></template><view v-else-if="mode==='recharge'" class="login"><text>充值金额由 CMS 再次校验并按站点比例兑换积分</text><input v-model.number="amount" type="number"/><button :disabled="busy||platform==='ios'" @click="recharge">创建充值订单</button></view><template v-else><view v-if="!orders.length" class="message">暂无订单</view><view v-for="o in orders" :key="o.order_code" class="plan"><text>{{o.order_code}}</text><text>¥{{o.order_price}} · {{Number(o.order_status)===1?'已支付':'待支付'}}</text><button v-if="Number(o.order_status)===0" :disabled="busy||platform==='ios'" @click="pending=o">选择此订单付款</button><button :disabled="busy" @click="check(o.order_code)">查询 CMS 支付状态</button></view></template><view v-if="pending" class="message"><text>订单 {{pending.order_code}} · ¥{{pending.order_price}}</text><view class="payment-methods"><text v-for="m in [{id:'alipay',name:'支付宝'},{id:'weixin',name:'微信'},{id:'epay',name:'易支付'},{id:'codepay',name:'码支付'},{id:'zhapay',name:'Z 支付'}]" :key="m.id" :class="{chosen:payMethod===m.id}" @click="payMethod=m.id;payUrl='';qrRows=[]">{{m.name}}</text></view><button :disabled="busy||platform==='ios'" @click="checkout()">生成 CMS 收银台</button><text>可用支付渠道以 CMS 配置为准。</text><view v-if="qrRows.length" class="qr"><view v-for="(row,r) in qrRows" :key="r" class="qr-row"><view v-for="(dark,c) in row" :key="c" class="qr-cell" :style="{background:dark?'#000':'#fff'}"/></view></view><button v-if="payUrl" @click="payment">前往付款</button><button :disabled="busy" @click="check(pending.order_code)">查询此订单状态</button></view></template><text class="footnote" v-if="platform==='ios'&&!accountOnly">iOS 内购等待配置 Apple 商品及服务端凭据。</text></view></template>
